// Código Arduino para variar la velocidad de un motor
int motorPin = 9; // Pin digital con soporte PWM
void setup() {
  pinMode(motorPin, OUTPUT);
}
void loop() {
  analogWrite(motorPin, 128); // ~50% de ciclo de trabajo (rango 0-255)
  delay(2000);
  analogWrite(motorPin, 255); // 100% velocidad máxima
  delay(2000);
}
